insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000010', 'en', null, 'Graphic Design Fundamentals', 'A hands-on tour of visual design — the elements and principles, color, type, and layout — building toward your own poster. Structure and content assembled from openly-licensed OER Commons material (CC BY).', null, 'work', 16, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000010', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Which of these is an *element* of design rather than a principle?","options":["balance","contrast","color","hierarchy"],"answer":2,"explanation":"Elements are the raw ingredients (line, shape, color, texture, space); principles are how you arrange them — see ''The elements''."},{"prompt":"On a standard color wheel, the primary colors are…","options":["red, green, blue","red, yellow, blue","cyan, magenta, yellow","orange, green, purple"],"answer":1,"explanation":"In traditional pigment theory the primaries are red, yellow, and blue — see ''Color theory''."},{"prompt":"Two colors directly opposite each other on the wheel are called…","options":["analogous","complementary","monochromatic","triadic"],"answer":1,"explanation":"Opposites are complementary and create strong contrast — see ''Color theory''."},{"prompt":"Visual hierarchy is mainly about…","options":["using expensive fonts","guiding the eye to what matters first","filling all empty space","making everything the same size"],"answer":1,"explanation":"Hierarchy ranks importance so the viewer knows where to look — see ''The principles''."},{"prompt":"A typeface with small strokes at the ends of letters is a…","options":["sans-serif","serif","script","monospace"],"answer":1,"explanation":"Those finishing strokes are serifs — see ''Typography''."},{"prompt":"The empty area around and between design elements is called…","options":["negative space","kerning","leading","saturation"],"answer":0,"explanation":"Negative (white) space is an active design tool — see ''The elements''."},{"prompt":"A grid in layout design is used to…","options":["decorate the background","create alignment and consistent structure","add more color","replace typography"],"answer":1,"explanation":"Grids organize content and keep alignment consistent — see ''Layout & composition''."},{"prompt":"A good logo is generally…","options":["highly detailed and photographic","simple, memorable, and works in one color","different on every product","as large as possible"],"answer":1,"explanation":"Simplicity and scalability define strong logos — see the vocab and project lessons."}]}'::jsonb, null, 10),
  (2, 'The elements of design', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the core visual elements — line, shape, color, texture, and space — and spot them in any design. Warm-up: from the diagnostic, which was an element rather than a principle?"},{"heading":"The idea","text":"Every design is built from a small set of *elements*. *Line* directs the eye and can divide or connect. *Shape* is any enclosed area — geometric (circles, squares) or organic. *Color* carries mood and attention. *Texture* is the sense of surface, real or implied. *Space* — especially *negative space*, the empty area around things — gives a design room to breathe. Picture a concert flyer: a bold diagonal line slashing across the page creates energy, a single circle frames the band photo, and generous negative space keeps the date readable instead of buried."},{"heading":"Worked example","text":"A student''s poster crams text edge to edge with no margins, so it feels loud and unreadable. The fix uses *space*: add a wide margin, group the title and date together, and let one strong *shape* — a colored bar behind the headline — anchor the eye. Nothing was deleted except clutter; the elements simply got room to work."},{"heading":"Your turn","text":"Identify the element at work: (1) a thin rule separating a header from body text, (2) the empty gap that makes a logo readable, (3) a rough, paper-like background feel, (4) a red call-to-action button on a gray page. Answers: (1) line, (2) space, (3) texture, (4) color."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating empty space as ''wasted'' — negative space is an active element, not a gap to fill. Mistake: confusing an element (color) with a principle (contrast). Exit: (a) Name the element that is the empty area around objects. (b) Is ''shape'' an element or a principle? Answers: (negative) space; an element."}]}'::jsonb, 'Elements are the ingredients; principles (next lesson) are the recipe.', 12),
  (3, 'The principles of design', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply the five workhorse principles — balance, contrast, hierarchy, alignment, and repetition — to arrange elements on purpose. Warm-up: which principle tells the viewer where to look first?"},{"heading":"The idea","text":"If elements are ingredients, *principles* are the recipe. *Balance* distributes visual weight so a layout feels stable (symmetric or asymmetric). *Contrast* makes differences — big vs. small, dark vs. light — that create interest and legibility. *Hierarchy* ranks importance so the eye lands on the headline before the fine print. *Alignment* connects elements along shared edges so nothing looks accidental. *Repetition* reuses colors, shapes, or type styles to make a design feel unified. On a movie poster the huge title (hierarchy), the light text on a dark sky (contrast), and the credits block aligned to the same edge as the title (alignment) all cooperate."},{"heading":"Worked example","text":"A flyer has three headings, each in a different font, size, and color, and centered text that wobbles because nothing shares an edge. Critique: no *hierarchy* (all headings shout equally) and no *alignment* (edges don''t line up). Improve it: pick one heading style and reuse it (*repetition*), make the most important line clearly largest (*hierarchy*), and left-align every block to a single invisible line (*alignment*). The page instantly reads as intentional."},{"heading":"Your turn","text":"Name the principle: (1) reusing the same accent color on every button, (2) a giant number ''1'' next to tiny caption text, (3) all captions sharing the same left edge, (4) a heavy image on the left balanced by a block of text on the right, (5) white text on a black bar. Answers: (1) repetition, (2) hierarchy, (3) alignment, (4) balance, (5) contrast."},{"heading":"Common mistakes & exit ticket","text":"Mistake: making everything bold or large ''for emphasis'' — if everything stands out, nothing does; hierarchy needs restraint. Mistake: centering everything and calling it balance — true alignment usually shares a real edge. Exit: (a) Which principle ranks importance? (b) Which reuses styles to unify a design? Answers: hierarchy; repetition."}]}'::jsonb, 'Principles arrange elements: balance, contrast, hierarchy, alignment, repetition.', 13),
  (4, 'Color theory', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use the color wheel to build harmonies and describe a color by hue, saturation, and value. Warm-up: what do we call two colors opposite each other on the wheel?"},{"heading":"The idea","text":"The *color wheel* organizes hues so relationships are visible. *Primary* colors (red, yellow, blue) mix into *secondary* colors (orange, green, purple). Three properties describe any color: *hue* (its name), *saturation* (intensity, from vivid to gray), and *value* (lightness, from pale to dark). Useful *harmonies*: *complementary* (opposites, high contrast — blue and orange), *analogous* (neighbors, calm and cohesive — blue, teal, green), and *monochromatic* (one hue at different values). Warm hues (red, orange) advance and feel energetic; cool hues (blue, green) recede and feel calm."},{"heading":"Worked example","text":"A café menu uses bright red text on a bright green background — both fully saturated complements, so the type vibrates and strains the eyes. Critique: complementary hues at equal, maximum saturation clash. Improve it: keep the green but drop its saturation to a soft sage, set the type in a dark near-black (a low *value* of the same family), and reserve pure red only for the small ''chef''s special'' tag. Same palette, but now contrast serves readability instead of fighting it."},{"heading":"Your turn","text":"Classify the scheme or property: (1) navy, sky blue, and pale blue, (2) purple and yellow together, (3) how gray-vs-vivid a color is, (4) red, orange, and yellow neighbors, (5) how light or dark a color is. Answers: (1) monochromatic, (2) complementary, (3) saturation, (4) analogous, (5) value."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using many fully saturated colors at once — it overwhelms; let most of the palette be muted and save vivid color for emphasis. Mistake: confusing value (lightness) with saturation (intensity). Exit: (a) Name the harmony made of neighbors on the wheel. (b) Which property is a color''s lightness? Answers: analogous; value."}]}'::jsonb, 'Hue = which color; saturation = how intense; value = how light or dark.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which is a *principle*, not an element?","options":["texture","space","alignment","line"],"answer":2,"explanation":"Alignment arranges elements; texture, space, and line are elements."},{"prompt":"Reusing the same color and type style throughout a design is…","options":["contrast","repetition","hierarchy","balance"],"answer":1,"explanation":"Repetition unifies a design."},{"prompt":"Red and green sit opposite each other, so they are…","options":["analogous","monochromatic","complementary","primary"],"answer":2,"explanation":"Opposites on the wheel are complementary."},{"prompt":"Saturation refers to a color''s…","options":["lightness","intensity","name","temperature"],"answer":1,"explanation":"Saturation is intensity; value is lightness; hue is the name."},{"prompt":"The purpose of visual hierarchy is to…","options":["fill empty space","make all text equal","guide the eye to what matters first","add texture"],"answer":2,"explanation":"Hierarchy ranks importance."},{"prompt":"Mixing two primary colors produces a…","options":["tertiary color","secondary color","neutral","complement"],"answer":1,"explanation":"Primary + primary = secondary (e.g. red + yellow = orange)."}]}'::jsonb, null, 8),
  (6, 'Typography', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell serif from sans-serif, pair typefaces sensibly, and use kerning and leading to improve readability. Warm-up: what do we call the little finishing strokes on letters?"},{"heading":"The idea","text":"*Typography* is arranging type to be legible and expressive. A *serif* typeface has small strokes at letter ends and feels traditional; a *sans-serif* has none and feels modern and clean. *Leading* is the vertical space between lines; too little feels cramped, too much breaks the flow. *Kerning* adjusts the space between individual letter pairs so words look even. A reliable habit: choose one typeface for headings and one for body text, and create *contrast* through weight and size rather than piling on many different fonts. Think of a wedding invitation pairing an elegant serif headline with a plain sans-serif for the details."},{"heading":"Worked example","text":"A poster sets a long paragraph in tightly packed lines of ALL CAPS, using four different fonts. Critique: all caps and tight *leading* slow reading, and four fonts destroy unity. Improve it: use sentence case, open up the leading so lines don''t collide, and cut down to two typefaces — one bold sans-serif headline and one readable serif for the paragraph. Emphasis now comes from size and weight, not font-hopping."},{"heading":"Your turn","text":"Name the term or choice: (1) the space between two adjacent letters, (2) the space between lines of text, (3) a font with no end-strokes, (4) how many typeface families a clean design usually uses, (5) the finishing strokes on a serif letter. Answers: (1) kerning, (2) leading, (3) sans-serif, (4) about two, (5) serifs."},{"heading":"Common mistakes & exit ticket","text":"Mistake: mixing many typefaces for variety — it looks chaotic; get variety from weight and size within one or two families. Mistake: setting long body text in all caps, which hurts readability. Exit: (a) Which adjusts space between two specific letters? (b) Serif or sans-serif has end-strokes? Answers: kerning; serif."}]}'::jsonb, 'Kerning = space between two letters; leading = space between lines.', 13),
  (7, 'Layout & composition with grids', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use a grid, margins, and the rule of thirds to compose a balanced, aligned layout. Warm-up: what invisible structure helps keep elements aligned?"},{"heading":"The idea","text":"*Composition* is how you arrange everything in the frame. A *grid* is an invisible framework of columns and rows that gives elements consistent *alignment* and spacing. *Margins* protect the edges so content doesn''t feel trapped, and *gutters* are the gaps between columns. The *rule of thirds* divides the frame into a 3×3 grid; placing key elements along those lines or at their intersections tends to feel more dynamic than dead-center. Grouping related items and separating unrelated ones (*proximity*) lets the reader parse the page at a glance — like a magazine spread where the headline, image, and caption each occupy clear grid zones."},{"heading":"Worked example","text":"A newsletter scatters items freely: the title floats center, images sit at random widths, and captions drift far from their photos. Critique: no *grid*, so nothing aligns, and weak *proximity* separates captions from images. Improve it: set a two-column grid, snap every image to a column edge, place each caption directly beneath its photo, and add even margins. The content didn''t change, but the eye now moves smoothly down organized columns."},{"heading":"Your turn","text":"Name the concept: (1) the protective empty band around the page edge, (2) an invisible column-and-row framework, (3) placing a subject a third of the way in rather than centered, (4) keeping a caption close to its image, (5) the gap between two columns. Answers: (1) margin, (2) grid, (3) rule of thirds, (4) proximity, (5) gutter."},{"heading":"Common mistakes & exit ticket","text":"Mistake: centering everything by default — off-center, grid-aligned layouts often feel more intentional. Mistake: ignoring margins so content jams the edges. Exit: (a) What is the gap between grid columns called? (b) What rule suggests placing a subject off-center? Answers: gutter; the rule of thirds."}]}'::jsonb, 'A grid is invisible in the final design but shapes every placement.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"negative space","translation":"the empty area around and between design elements, used deliberately","example":"Generous negative space made the logo feel premium and clear."},{"term":"hierarchy","translation":"the arrangement of elements to signal their order of importance","example":"A large headline over small captions establishes hierarchy."},{"term":"complementary colors","translation":"two colors opposite on the color wheel, producing strong contrast","example":"Blue and orange are complementary, so they pop against each other."},{"term":"kerning","translation":"the adjustment of space between individual pairs of letters","example":"Careful kerning kept the wordmark from looking uneven."},{"term":"grid","translation":"an invisible framework of columns and rows that aligns a layout","example":"Snapping images to the grid made the page feel organized."},{"term":"brand identity","translation":"the consistent visual system — logo, colors, and type — that makes an organization recognizable","example":"A simple logo and fixed palette gave the café a strong brand identity."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Leading refers to the space…","options":["between two letters","between lines of text","around the page edge","between columns"],"answer":1,"explanation":"Leading is vertical line spacing; kerning is between letters."},{"prompt":"A clean design usually limits itself to about…","options":["one color only","two typeface families","six fonts","no repetition"],"answer":1,"explanation":"Roughly two typefaces keeps a design unified; variety comes from weight and size."},{"prompt":"The gap between two columns in a grid is a…","options":["margin","gutter","serif","leading"],"answer":1,"explanation":"Gutters separate columns; margins protect the outer edges."},{"prompt":"The rule of thirds suggests placing key elements…","options":["dead center","along a 3×3 grid''s lines","at the very edge","randomly"],"answer":1,"explanation":"Off-center placement on the thirds tends to feel more dynamic."},{"prompt":"A strong logo should ideally…","options":["be highly detailed","work even in a single color","change per product","be as large as possible"],"answer":1,"explanation":"Simplicity and scalability, including one-color use, mark a strong logo."},{"prompt":"Keeping a caption near its photo is an example of…","options":["contrast","proximity","saturation","kerning"],"answer":1,"explanation":"Proximity groups related items so they read together."}]}'::jsonb, null, 8),
  (10, 'Applied project: design a poster', 'writing', '{"sections":[{"heading":"The task","text":"Design a one-page event poster — in words. Pick a real or imagined event (a concert, a lecture, a community market) and write a plan describing your design choices and the reason behind each one. You won''t open any software; you''ll justify a complete composition on paper."},{"heading":"Milestones","text":"1) State the event and the single most important message the poster must deliver. 2) Describe your layout: the grid or margins you''d use and where the title, image, and details go. 3) Name your color palette (hues and one harmony — complementary, analogous, or monochromatic) and say what mood it sets. 4) Choose your typography: one headline typeface and one body typeface, and explain the contrast between them. 5) Point to at least three principles you used (balance, contrast, hierarchy, alignment, repetition) and where each appears."},{"heading":"Self-check rubric","text":"✔ The most important message is unmistakably the largest, clearest element (hierarchy). ✔ Every block aligns to a shared edge or grid. ✔ Your color choices name a specific harmony and justify the mood. ✔ You used at most two typefaces and explained their contrast. ✔ You can point to three named principles in your own design. If all five hold, you''ve composed like a designer — with reasons, not just taste."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000010' and l.position = v.pos
);
